INSERT INTO artists (id, slug, name, bio, photo_url, speciality) VALUES
  ('artist-1', 'elena-vasquez', 'Elena Vasquez', 'Elena Vasquez is a contemporary painter known for her bold use of colour and sweeping abstract landscapes. Born in Buenos Aires, she moved to Montreal to study fine arts and never left. Her work explores the tension between memory and place.', 'https://picsum.photos/seed/artist-elena/400/400', 'Abstract Painting'),
  ('artist-2', 'james-okafor', 'James Okafor', 'James Okafor is a Nigerian-Canadian photographer whose documentary-style portraits capture everyday resilience in urban communities. His work has been featured in galleries across Toronto and Lagos.', 'https://picsum.photos/seed/artist-james/400/400', 'Documentary Photography'),
  ('artist-3', 'mei-lin-chen', 'Mei-Lin Chen', 'Mei-Lin Chen creates intricate woodblock prints that blend traditional East Asian techniques with modern surrealist imagery. Based in Vancouver, her limited-edition prints sell out within hours of release.', 'https://picsum.photos/seed/artist-mei/400/400', 'Printmaking'),
  ('artist-4', 'david-thornton', 'David Thornton', 'David Thornton is a sculptor working in reclaimed metal and found objects. His large-scale installations comment on consumer culture and environmental decay. He maintains a studio in Calgary''s Inglewood district.', 'https://picsum.photos/seed/artist-david/400/400', 'Metal Sculpture'),
  ('artist-5', 'sofia-andersson', 'Sofia Andersson', 'Sofia Andersson''s oil paintings are luminous studies of light on water. Originally from Stockholm, she draws inspiration from the Alberta foothills where she now lives, translating Nordic minimalism into Western Canadian landscapes.', 'https://picsum.photos/seed/artist-sofia/400/400', 'Landscape Painting'),
  ('artist-6', 'marcus-reid', 'Marcus Reid', 'Marcus Reid is a fine-art photographer specializing in long-exposure night photography. His haunting images of empty urban spaces have earned him a devoted collector base and multiple national awards.', 'https://picsum.photos/seed/artist-marcus/400/400', 'Fine Art Photography'),
  ('artist-7', 'priya-sharma', 'Priya Sharma', 'Priya Sharma creates vibrant mixed-media paintings that weave together South Asian textile patterns with Western pop art sensibilities. Her work is a celebration of cultural hybridity and belonging.', 'https://picsum.photos/seed/artist-priya/400/400', 'Mixed Media'),
  ('artist-8', 'lucas-fontaine', 'Lucas Fontaine', 'Lucas Fontaine is a Québécois printmaker and illustrator whose risograph prints explore themes of solitude, nature, and digital disconnection. He runs a small press out of his Montréal studio.', 'https://picsum.photos/seed/artist-lucas/400/400', 'Risograph & Illustration');
