  ('art-68', 'seasonal-shift-68', 'Seasonal Shift', 'artist-8', 'print', '16" × 20"', 1750, 2025, 'A striking print work by the artist, created in 2025. This piece explores themes of form, colour, and space through the lens of contemporary practice.', 'https://picsum.photos/seed/seasonal-shift-68/800/600', '{"landscape","new"}');
INSERT INTO editorials (slug, title, subtitle, author, date, hero_image_url, content, pull_quote, related_artist_id) VALUES
  ('colour-as-memory', 'Colour as Memory', 'How Elena Vasquez translates the landscapes of her childhood into abstract form.', 'Canvas Editorial', '2026-10-15', 'https://picsum.photos/seed/editorial-1/1600/700', '{"Elena Vasquez doesn''t paint what she sees. She paints what she remembers feeling. Standing in her sun-drenched Montreal studio, surrounded by canvases in various stages of completion, she explains her process with characteristic directness.",""I grew up watching the pampas change colour with the seasons. That palette — those ochres, those deep greens — they''re in my muscle memory. When I pick up a brush, my hand already knows what colour it wants."","Her latest series, shown here on Canvas, pushes this idea further than ever. The landscapes are barely recognizable as landscapes at all. What remains is emotion: the warmth of a late-summer afternoon, the melancholy of an overcast morning."}', 'When I pick up a brush, my hand already knows what colour it wants.', 'artist-1'),
  ('the-quiet-city', 'The Quiet City', 'Marcus Reid photographs urban spaces after everyone has gone home.', 'Canvas Editorial', '2026-09-28', 'https://picsum.photos/seed/editorial-2/1600/700', '{"There''s a version of every city that only exists between 2 and 5 AM. Marcus Reid has spent the last decade documenting it.","His long-exposure photographs transform familiar streets into something otherworldly. Traffic lights bleed colour across wet asphalt. Empty storefronts glow with the residual warmth of fluorescent tubes.",""I''m interested in the city as a stage after the performance is over," Reid says. "The set is still lit, but the actors have gone home. That''s when the space gets to be itself.""}', 'The set is still lit, but the actors have gone home. That''s when the space gets to be itself.', 'artist-6'),
  ('from-block-to-paper', 'From Block to Paper', 'Inside Mei-Lin Chen''s meticulous printmaking process.', 'Canvas Editorial', '2026-09-10', 'https://picsum.photos/seed/editorial-3/1600/700', '{"Mei-Lin Chen''s studio smells like ink and cedar. Woodblocks in various stages of carving cover every surface.","Each print begins with a drawing — always by hand, never digital. Chen transfers the image to the block and carves for days, sometimes weeks.",""People assume prints are reproductions," she says. "But every impression is unique. The pressure of my hand, the moisture in the paper — they all leave their mark.""}', 'Every impression is unique. The pressure of my hand, the moisture in the paper — they all leave their mark.', 'artist-3'),
  ('metal-and-meaning', 'Metal and Meaning', 'David Thornton turns scrap into sculpture — and commentary.', 'Canvas Editorial', '2026-08-20', 'https://picsum.photos/seed/editorial-4/1600/700', '{"David Thornton''s sculptures begin their lives as something else. Car parts. Kitchen appliances. Industrial piping.",""Everything we throw away tells a story about what we valued and then stopped valuing," Thornton explains, welding torch in hand.","His latest series of wall-mounted works hangs in the gallery like a collection of mechanical butterflies pinned to a board."}', 'Everything we throw away tells a story about what we valued and then stopped valuing.', 'artist-4'),
  ('between-two-worlds', 'Between Two Worlds', 'Priya Sharma''s paintings live at the intersection of heritage and pop culture.', 'Canvas Editorial', '2026-08-01', 'https://picsum.photos/seed/editorial-5/1600/700', '{"Priya Sharma''s canvases are busy in the best way. They layer paisley patterns over comic-book panels, Bollywood palette over Warhol repetition.",""I grew up code-switching," Sharma says. "At home it was one culture, at school another. My work is what happens when you stop switching and let everything exist at once."","Her pieces resist the pressure to be one thing. Collectors respond to their energy — Sharma''s last show sold out on opening night."}', 'My work is what happens when you stop switching and let everything exist at once.', 'artist-7');
